import { chromium } from 'playwright';
const b = await chromium.launch({headless:true});
const p = await b.newPage();
await p.goto('http://127.0.0.1:54569');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForURL('**/dashboard');
await p.goto('http://127.0.0.1:54569/pipeline');
const names = () => p.$$eval('#pl .nm', els => els.map(e => e.textContent));
async function drag(name, targetName, above) {
  const li = p.locator('#pl li', { has: p.locator('.nm', { hasText: new RegExp('^'+name+'$') }) });
  const h = li.locator('.h');
  const hb = await h.boundingBox();
  const tli = p.locator('#pl li', { has: p.locator('.nm', { hasText: new RegExp('^'+targetName+'$') }) });
  const tb = await tli.boundingBox();
  await p.mouse.move(hb.x+hb.width/2, hb.y+hb.height/2);
  await p.mouse.down();
  const ty = above ? tb.y + 2 : tb.y + tb.height - 2;
  await p.mouse.move(hb.x+hb.width/2, ty, {steps: 20});
  await p.mouse.up();
  await p.waitForTimeout(200);
}
console.log('before', await names());
await drag('Invoicing', 'Picking', true);
console.log('after1', await names());
await drag('Packing', 'Shipping', true);
console.log('after2', await names());
await p.click('#save');
await p.waitForTimeout(500);
console.log('msg', await p.textContent('#done'));
await p.reload();
console.log('reloaded', await names());
await b.close();
EOF
